for(const [level,items] of Object.entries(extraDrills))items.forEach((q,i)=>{q.id=`${level.toLowerCase()}-extra-${i+1}`;if(q.options){const shift=(i+1)%3;q.options=q.options.slice(shift).concat(q.options.slice(0,shift));q.answer=(3-shift)%3;}});

const readingQ=(prompt,answer,other,why,whyEn)=>({prompt,options:[answer,...other],answer:0,why,whyEn});
export const extraLibrary=[
 {id:'lib-b1-3',level:'B1',title:'Un piso para septiembre',type:'Correo',text:'Hola, Laura: He visitado el piso del que te hablé. Está cerca de la estación, pero no da directamente a la calle principal. Las ventanas del salón dan a un patio grande y entra bastante luz por la mañana. Hay dos dormitorios: uno tiene armario y el otro es más pequeño. La propietaria dijo que podemos usarlo como habitación de trabajo, aunque no hay una mesa. El alquiler incluye los gastos de la comunidad, pero no la electricidad ni el agua. El contrato empezaría el primero de septiembre. Yo pensaba mudarme una semana antes, así que tendría que buscar otro sitio para esos días. La propietaria puede enseñártelo el miércoles por la tarde; el jueves no estará en la ciudad. Nos ha pedido una respuesta antes del viernes, pero no tenemos que pagar nada hasta leer y aceptar el contrato. No quiero decidir solo porque me gusta el barrio. Me preocupa que el dormitorio pequeño sea demasiado estrecho para tus cosas. He hecho fotos y voy a enviártelas esta noche. Si puedes venir el miércoles, comprobaremos también el ruido a esa hora. Por ahora, no he reservado el piso. Dime qué dudas quieres preguntar para que no se nos olvide nada durante la visita.',translation:'Hi Laura: I visited the apartment I told you about. It is near the station, but it does not face the main street directly. The living-room windows face a large courtyard and get quite a lot of morning light. There are two bedrooms: one has a wardrobe and the other is smaller. The owner said we can use it as a work room, although there is no desk. Rent includes building fees, but not electricity or water. The contract would start on September first. I was planning to move a week earlier, so I would need somewhere else for those days. The owner can show it to you on Wednesday afternoon; she will be out of town on Thursday. She has asked for an answer before Friday, but we do not need to pay anything until we read and accept the contract. I do not want to decide just because I like the neighbourhood. I worry that the small bedroom may be too narrow for your things. I took photos and will send them tonight. If you can come on Wednesday, we will also check the noise then. I have not reserved the apartment yet. Tell me what you want to ask so we do not forget anything during the visit.',glossary:[['dar a','to face / look onto'],['gastos de la comunidad','building maintenance fees'],['estrecho','narrow'],['reservar','to reserve']],questions:[
 readingQ('¿A dónde dan las ventanas del salón?','A un patio.',['A la calle principal.','A un dormitorio.'],'El correo indica que dan a un patio grande, aunque el piso está cerca de la estación.','The windows face a courtyard; the apartment’s proximity to the station does not change that.'),
 readingQ('¿Qué gasto está incluido?','La comunidad.',['Toda la electricidad.','El agua.'],'Se incluyen los gastos de la comunidad; electricidad y agua se excluyen expresamente.','Building fees are included; electricity and water are explicitly excluded.'),
 readingQ('¿Por qué necesita quizá otro alojamiento?','Quiere mudarse antes del inicio del contrato.',['El piso no tiene dormitorios.','La propietaria canceló el contrato.'],'Pensaba mudarse una semana antes del primero de septiembre, cuando empezaría el contrato.','The intended move is a week before the contract starts.'),
 readingQ('¿Cuándo puede Laura visitar el piso con la propietaria?','El miércoles por la tarde.',['El jueves en cualquier momento.','Después del viernes solamente.'],'El miércoles es la propuesta; el jueves la propietaria estará fuera de la ciudad.','Wednesday afternoon is offered; the owner will be away on Thursday.'),
 readingQ('¿Se ha reservado ya el piso?','No.',['Sí, y ya está pagado.','Sí, desde hace una semana.'],'El remitente afirma explícitamente que por ahora no ha reservado el piso.','The sender explicitly says it has not been reserved.'),
 readingQ('¿Qué quiere comprobar además del tamaño?','El ruido durante la visita.',['El horario de Laura en Florida.','La existencia de una piscina.'],'Propone comprobar también el ruido a la hora de la visita; no menciona una piscina.','The sender proposes checking noise at the time of the visit.')],task:'Resume para Laura qué está confirmado, qué falta por comprobar y qué fecha importa.',taskEn:'Summarise what is confirmed, what still needs checking and which date matters.'},
 {id:'lib-b1-4',level:'B1',title:'Una devolución con condiciones',type:'Diálogo resumido',text:'El lunes fui a una tienda para devolver una chaqueta que había comprado el sábado. La talla parecía correcta cuando me la probé, pero en casa vi que las mangas me quedaban cortas. Llevé el recibo y la chaqueta con todas las etiquetas. La dependienta me explicó que podía devolverla porque todavía estaba dentro del plazo de quince días. Antes de hacer la devolución, me ofreció probar una talla más. La chaqueta más grande me quedaba mejor de mangas, pero era demasiado ancha. Decidí no cambiarla. Entonces me preguntó cómo había pagado. Le dije que había usado una tarjeta, y me explicó que la devolución debía hacerse a esa misma tarjeta. Yo no la llevaba porque había salido solo con el móvil. La dependienta podía iniciar la gestión, pero necesitaba que volviera con la tarjeta para terminarla. Me guardó la chaqueta detrás del mostrador y me dio un comprobante. No recibí el dinero ese día. Volví el martes y completamos la devolución. Me advirtió que el importe podía tardar unos días en aparecer en mi cuenta. Ahora compruebo las mangas moviendo los brazos antes de decidir una compra. También guardo el recibo hasta estar segura de que voy a quedarme la ropa. Esta historia describe lo que ocurrió en esa tienda; no establece una política universal de devoluciones.',translation:'On Monday I went to a shop to return a jacket I had bought on Saturday. The size seemed right when I tried it on, but at home I saw that the sleeves were too short. I took the receipt and the jacket with all its tags. The assistant explained that I could return it because I was still within the fifteen-day period. Before processing the return, she offered a larger size. Its sleeves fit better, but it was too wide. I decided not to exchange it. Then she asked how I had paid. I said I had used a card, and she explained that the refund had to go to that same card. I did not have it because I had gone out with only my phone. She could start the process, but I had to come back with the card to finish it. She kept the jacket behind the counter and gave me a slip. I did not receive the money that day. I returned on Tuesday and completed the return. She warned that the amount might take a few days to appear in my account. Now I check sleeves by moving my arms before buying. I also keep the receipt until I am sure I will keep the clothes. This story describes what happened in that shop; it does not establish a universal returns policy.',glossary:[['me quedaban cortas','they were too short on me'],['etiqueta','tag'],['mostrador','counter'],['comprobante','confirmation slip']],questions:[
 readingQ('¿Qué problema tenía la chaqueta original?','Las mangas eran cortas.',['No tenía etiquetas.','Había perdido el recibo.'],'El problema se detectó en casa y afectaba a las mangas, no a la documentación.','The problem was sleeve length, not missing documents.'),
 readingQ('¿Por qué rechazó la talla más grande?','Era demasiado ancha.',['Las mangas eran aún más cortas.','Costaba el doble, según el texto.'],'La talla grande mejoraba las mangas, pero resultaba ancha. No se da otro precio.','The sleeves improved, but the jacket became too wide.'),
 readingQ('¿Qué necesitaba para completar la devolución?','La tarjeta con la que pagó.',['Una tarjeta nueva.','Una firma de su pareja.'],'La dependienta indicó que la devolución debía hacerse a la misma tarjeta.','The refund had to use the original card.'),
 readingQ('¿Cuándo completó la devolución?','El martes.',['El lunes, sin volver.','El sábado de la compra.'],'El lunes inició la gestión; el martes volvió con la tarjeta y la completó.','The process started on Monday and was completed on Tuesday.'),
 readingQ('¿Se garantizó que el dinero aparecería al instante?','No; podía tardar unos días.',['Sí, inmediatamente.','Sí, antes de salir el lunes.'],'La advertencia sobre unos días impide interpretar una devolución instantánea en la cuenta.','The warning about several days rules out a guaranteed instant credit.'),
 readingQ('¿Describe una norma válida para todas las tiendas?','No, solo esta experiencia.',['Sí, una política universal.','Sí, una ley que se cita.'],'La última frase limita expresamente el alcance del relato a esa tienda.','The final sentence explicitly limits the story to that shop.')],task:'Cuenta el orden de los acontecimientos y distingue empezar una gestión de terminarla.',taskEn:'Retell the timeline and distinguish starting the process from completing it.'},
 {id:'lib-b2-3',level:'B2',title:'Aprender con una pantalla apagada',type:'Artículo',text:'En el grupo de estudio de Julia, algunas personas subrayan casi todas las líneas y después vuelven a leer el capítulo. Julia también lo hacía, hasta que decidió comprobar qué recordaba sin tener el texto delante. Descubrió que reconocía muchos conceptos al verlos, pero le costaba explicarlos. El grupo propuso una prueba de cuatro semanas: al final de cada sesión cerrarían el material y escribirían tres preguntas sobre lo estudiado. En la sesión siguiente responderían antes de consultar las notas. La propuesta no consistía en prohibir la lectura ni en competir por una puntuación. Buscaba detectar qué relaciones no se habían entendido. Hubo dificultades: algunas preguntas eran demasiado vagas y otras pedían detalles que nadie consideraba relevantes. Por eso acordaron compartir dos ejemplos de buenas preguntas y revisar las demás juntos. Al terminar el mes, varias personas dijeron que podían resumir mejor, aunque no todas habían mantenido la rutina. El grupo no realizó un estudio con comparación controlada ni puede atribuir cada mejora al método. Julia cree que el cambio más útil fue observar sus errores sin esperar al examen final. Ahora combina lectura, preguntas de recuperación y ejemplos propios. Si un concepto sigue sin quedar claro, vuelve al capítulo o pide una explicación. Para ella, cerrar la pantalla es una manera de comprobar, no una demostración de que estudiar sin materiales sea siempre superior.',translation:'In Julia’s study group, some people highlight almost every line and then reread the chapter. Julia did too, until she tested what she remembered without the text in front of her. She found that she recognised many concepts when she saw them but struggled to explain them. The group proposed a four-week trial: at the end of each session they would close the material and write three questions about it. In the next session they would answer before checking their notes. The proposal did not ban reading or turn scores into a competition. It aimed to find relationships that had not been understood. There were difficulties: some questions were too vague and others asked for details nobody considered relevant. They therefore shared two examples of good questions and reviewed the rest together. At the end of the month, several people said they could summarise better, though not everyone had kept the routine. The group did not conduct a controlled comparison and cannot attribute every improvement to the method. Julia thinks the most useful change was noticing errors without waiting for the final exam. She now combines reading, retrieval questions and her own examples. If something remains unclear, she returns to the chapter or asks for an explanation. For her, closing the screen is a way of checking, not proof that studying without materials is always better.',glossary:[['subrayar','to highlight / underline'],['recuperación','retrieval / recall'],['vago','vague'],['atribuir','to attribute']],questions:[
 readingQ('¿Qué diferencia descubrió Julia?','Reconocer conceptos no garantizaba poder explicarlos.',['No reconocía ninguna palabra.','Todos los capítulos eran inútiles.'],'Reconocía conceptos al verlos, pero le costaba explicarlos sin el texto.','Recognition did not guarantee explanation without the text.'),
 readingQ('¿Cuándo respondían a las preguntas?','En la sesión siguiente, antes de consultar.',['Solo después de mirar todas las notas.','Durante el examen final únicamente.'],'La rutina separa crear preguntas y recuperarlas en la sesión siguiente.','They answered in the next session before checking notes.'),
 readingQ('¿Qué problema encontraron?','La calidad de algunas preguntas.',['La prohibición de leer cualquier texto.','La desaparición de todas las notas.'],'Había preguntas vagas o centradas en detalles poco relevantes.','Some questions were vague or focused on irrelevant details.'),
 readingQ('¿Qué concluye el texto sobre causalidad?','No permite atribuir toda mejora al método.',['Demuestra que el método es superior para todos.','Prueba que nadie mejoró.'],'No hubo comparación controlada; los testimonios no justifican una atribución total.','Without a controlled comparison, reports do not justify attributing every improvement to the method.'),
 readingQ('¿Cómo estudia ahora Julia?','Combina métodos y consulta cuando hace falta.',['Ha abandonado toda lectura.','Solo memoriza respuestas ajenas.'],'Combina lectura, recuperación y ejemplos propios, y vuelve a consultar si algo sigue confuso.','She combines reading, retrieval and personal examples and still consults material when needed.'),
 readingQ('¿Qué función tiene cerrar la pantalla?','Comprobar lo aprendido.',['Prohibir materiales permanentemente.','Sustituir cualquier explicación.'],'La frase final lo presenta como comprobación, con un alcance limitado.','The final sentence frames it as a check with a limited claim.')],task:'Resume la propuesta, una dificultad y el límite de la conclusión, sin convertir un testimonio en una prueba.',taskEn:'Summarise the proposal, one difficulty and the limit of the conclusion without turning testimony into proof.'},
 {id:'lib-b2-4',level:'B2',title:'Un horario que no sirve igual a todos',type:'Reunión resumida',text:'La biblioteca del barrio quiere ampliar su horario, pero dispone de presupuesto para una sola franja adicional. En la reunión, Marcos propuso abrir los domingos por la mañana. Según él, ayudaría a quienes trabajan entre semana. Elena prefería prolongar dos tardes hasta las nueve, porque muchas personas salen del trabajo a las siete. La directora explicó que no podían contratar más personal de forma indefinida y que cualquier cambio debía probarse durante dos meses. Además, el servicio de préstamo requeriría una persona distinta de la encargada de vigilar la sala. Una estudiante sugirió abrir solo la sala de estudio, sin préstamos, en la nueva franja. La propuesta reducía algunas necesidades de personal, pero no eliminaba el coste de vigilancia. Nadie afirmó que esa opción resolviera todos los problemas. Antes de votar, acordaron recoger las preferencias de los usuarios mediante una encuesta breve. También preguntarían si las personas realmente acudirían en la franja elegida, no solo si les parecía una buena idea. Marcos aceptó esperar a esos datos, siempre que la decisión no se aplazara todo el curso. La reunión terminó con una fecha para revisar la encuesta. Todavía no se había elegido el nuevo horario. Elena señaló que una prueba con pocas visitas no demostraría necesariamente falta de interés: también habría que comprobar si la información sobre la ampliación había llegado a los usuarios.',translation:'The neighbourhood library wants longer opening hours but has funding for just one additional time slot. At the meeting, Marcos proposed Sunday mornings, saying this would help people who work during the week. Elena preferred extending two evenings until nine because many people finish work at seven. The director explained that they could not hire more staff indefinitely and that any change had to be tested for two months. Lending would also need a staff member separate from the person supervising the room. A student suggested opening only the study room, without lending, in the new slot. This reduced some staffing needs but did not remove supervision costs. Nobody claimed it solved every problem. Before voting, they agreed to collect preferences through a short survey. They would also ask whether people would actually attend, not just whether it sounded good. Marcos accepted waiting for the data provided the decision was not delayed for the whole academic year. The meeting ended with a date to review the survey. No new schedule had been chosen yet. Elena noted that a trial with few visits would not necessarily prove a lack of interest: they would also need to check whether information about the extension had reached users.',glossary:[['franja','time slot'],['préstamo','lending / loan'],['aplazar','to postpone'],['acudir','to attend / come']],questions:[
 readingQ('¿Qué limita inicialmente la ampliación?','El presupuesto para una sola franja.',['La falta absoluta de usuarios.','Una prohibición de abrir tardes.'],'El texto establece un presupuesto para una franja, no una prohibición general.','The stated limit is funding for one slot, not a blanket ban.'),
 readingQ('¿Qué diferencia hay entre las propuestas?','Domingo por la mañana frente a tardes más largas.',['Ambas proponen exactamente el mismo horario.','Marcos quiere cerrar y Elena abrir.'],'Marcos propone domingos; Elena prolongar dos tardes.','Marcos proposes Sundays; Elena proposes longer evenings.'),
 readingQ('¿Abrir solo la sala elimina todos los costes?','No; sigue haciendo falta vigilancia.',['Sí, todos desaparecen.','Sí, incluida la contratación indefinida.'],'La propuesta reduce algunas necesidades, pero no elimina la vigilancia.','The proposal reduces some needs but retains supervision costs.'),
 readingQ('¿Qué quieren distinguir en la encuesta?','Una valoración positiva y la intención de acudir.',['Lectura y escritura de exámenes.','Usuarios y personal sin preguntar preferencias.'],'Considerar buena una idea no implica utilizar efectivamente la nueva franja.','Thinking an idea is good is not the same as intending to use the slot.'),
 readingQ('¿Cuál es el resultado de la reunión?','Una fecha de revisión, sin horario definitivo.',['La apertura inmediata todos los domingos.','El rechazo de toda ampliación.'],'Acuerdan revisar la encuesta; el horario aún no se ha elegido.','They schedule a review, but have not chosen the hours.'),
 readingQ('¿Qué reserva introduce Elena?','La comunicación podría afectar a las visitas.',['Pocas visitas siempre prueban desinterés.','Las encuestas no pueden contener preguntas.'],'Propone comprobar si la información llegó a los usuarios antes de interpretar pocas visitas.','She asks whether users heard about the change before interpreting low attendance.')],task:'Redacta una nota para alguien que no asistió: opciones, límites y siguiente decisión.',taskEn:'Write a note for someone absent from the meeting: options, constraints and the next decision.'},
 {id:'lib-c1-3',level:'C1',title:'El éxito que depende de cómo se cuenta',type:'Análisis',text:'El informe municipal presenta la nueva aplicación de reservas como un éxito: el número de operaciones digitales aumentó un cuarenta por ciento respecto del semestre anterior. La cifra resulta llamativa, pero no basta para saber si el servicio ha mejorado en conjunto. El documento aclara que, durante el mismo periodo, se redujeron los puntos de atención presencial y que varias gestiones pasaron a tramitarse exclusivamente en línea. Por tanto, una parte del aumento podría responder a un cambio de canal más que a una preferencia espontánea. Tampoco se informa de cuántas reservas se completaron sin ayuda de otra persona. Eso no invalida el dato publicado; limita las conclusiones que podemos extraer de él. Una evaluación más útil distinguiría disponibilidad del servicio, facilidad de uso y acceso para distintos perfiles. El informe sí menciona menos llamadas para confirmar citas, aunque no compara el tiempo que los usuarios dedican a resolver errores en la aplicación. Quienes defienden la herramienta sostienen que las dificultades iniciales disminuirán con formación. Sus críticos responden que esa formación no debería convertirse en una condición implícita para acceder a un servicio básico. Ambas posiciones plantean preguntas pertinentes, pero ninguna queda resuelta por la cifra del cuarenta por ciento. Antes de declarar un éxito o un fracaso, convendría definir qué resultado se quiere mejorar y para quién. Una medida puede facilitar la gestión interna mientras desplaza parte del trabajo hacia los usuarios.',translation:'The municipal report presents the new booking app as a success: digital transactions rose forty percent compared with the previous half-year. The figure is striking but insufficient to show that the service improved overall. The report explains that in the same period in-person service points were reduced and several procedures moved exclusively online. Part of the rise could therefore reflect a change of channel rather than spontaneous preference. It also does not say how many bookings were completed without another person’s help. This does not invalidate the published figure; it limits the conclusions we can draw. A more useful evaluation would distinguish availability, usability and access for different groups. The report mentions fewer calls to confirm appointments but does not compare time spent resolving app errors. Supporters argue that early difficulties will decrease with training. Critics respond that training should not become an implicit condition for accessing a basic service. Both raise relevant questions, but neither is resolved by the forty-percent figure. Before declaring success or failure, we should define the outcome to improve and for whom. A measure may streamline internal management while shifting some work onto users.',glossary:[['tramitar','to process'],['extraer conclusiones','to draw conclusions'],['pertinente','relevant'],['desplazar','to shift']],questions:[
 readingQ('¿Qué cuestiona principalmente el análisis?','La amplitud de la conclusión basada en una cifra.',['La existencia de cualquier operación digital.','Que se publicara un informe.'],'Acepta el dato como publicado, pero limita lo que puede demostrar sobre una mejora global.','It does not reject the figure; it questions the breadth of the conclusion drawn from it.'),
 readingQ('¿Qué explicación alternativa ofrece para el aumento?','El traslado obligatorio de algunas gestiones al canal digital.',['La apertura de más oficinas presenciales.','Una caída demostrada del número de trámites.'],'La reducción presencial y la exclusividad en línea pueden cambiar el canal utilizado.','Reduced in-person access and online-only procedures can drive channel changes.'),
 readingQ('¿Qué dato falta sobre autonomía?','Cuántas reservas se completaron sin ayuda.',['El porcentaje del aumento, que sí se da.','La existencia del semestre anterior.'],'El texto señala que no se informa del uso independiente de la aplicación.','The text explicitly identifies independent completion as missing information.'),
 readingQ('¿Qué preocupación tienen los críticos sobre formación?','Que sea un requisito implícito de acceso.',['Que se prohíba toda formación.','Que el informe demuestre exactamente su duración.'],'No rechazan toda formación; cuestionan que acceder dependa implícitamente de ella.','They question training as an implicit access requirement, not all training.'),
 readingQ('¿Qué puede ocurrir según la última frase?','Una mejora interna puede trasladar trabajo al usuario.',['La gestión interna y el esfuerzo del usuario siempre mejoran juntos.','La aplicación elimina todo error necesariamente.'],'El cierre distingue eficiencia organizativa y carga sobre las personas usuarias.','The ending separates organisational efficiency from work borne by users.'),
 readingQ('¿Qué propone hacer antes de valorar el resultado?','Definir qué mejorar y para quién.',['Elegir siempre el fracaso.','Repetir la cifra sin añadir criterios.'],'La conclusión exige precisar objetivo y destinatarios antes de una valoración global.','The conclusion calls for specifying the outcome and target users first.')],task:'Sintetiza el dato y tres límites. Conserva las reservas sin afirmar que la aplicación haya fracasado.',taskEn:'Summarise the figure and three limits without claiming the app has failed.'},
 {id:'lib-c1-4',level:'C1',title:'La invitación que parecía una crítica',type:'Relato reflexivo',text:'Cuando Inés presentó su borrador, el coordinador dijo que era un punto de partida interesante y preguntó si podría reducir la introducción. Ella oyó sobre todo la palabra reducir y salió convencida de que el texto no servía. Más tarde, una compañera que había asistido a la reunión le señaló que también se habían elogiado los ejemplos y que el cambio solicitado afectaba a una sección concreta. Inés decidió volver a preguntar en lugar de reconstruir la intención a partir de una sola frase. El coordinador explicó que la introducción ocupaba casi la mitad del espacio disponible y que el público ya conocía buena parte del contexto. No pedía eliminar el argumento, sino dejar más espacio para la propuesta. La aclaración no significa que toda crítica formulada con cortesía sea positiva ni que las impresiones de Inés fueran absurdas. Había una discrepancia entre lo que se dijo, lo que ella destacó y lo que necesitaba comprobar. Después de revisar el texto, añadió al correo dos preguntas sobre los criterios de extensión. El coordinador respondió con un ejemplo, aunque dejó claro que no había una única estructura válida. Inés conservó una parte de la introducción y reorganizó el resto. Lo más útil no fue descubrir una fórmula para interpretar cualquier comentario, sino aprender a pedir información sobre el alcance de una observación. El tono puede orientar, pero no sustituye el contexto ni garantiza por sí solo una intención.',translation:'When Inés presented her draft, the coordinator called it an interesting starting point and asked whether she could shorten the introduction. She focused on the word shorten and left convinced that the text was unusable. Later, a colleague who had attended noted that the examples had also been praised and that the requested change concerned one section. Inés chose to ask again instead of reconstructing the intention from one phrase. The coordinator explained that the introduction took nearly half the available space and that the audience already knew much of the background. He was not asking her to remove the argument but to leave more room for the proposal. This does not mean that every politely worded criticism is positive or that Inés’s impressions were absurd. There was a mismatch between what was said, what she focused on and what needed checking. After revising, she added two questions about length criteria to her email. The coordinator gave an example but made clear that there was no single valid structure. Inés kept part of the introduction and reorganised the rest. The useful lesson was not a formula for interpreting every comment but learning to ask about the scope of an observation. Tone can guide interpretation, but it neither replaces context nor guarantees an intention by itself.',glossary:[['borrador','draft'],['alcance','scope'],['observación','comment / observation'],['discrepancia','mismatch / disagreement']],questions:[
 readingQ('¿En qué se centró inicialmente Inés?','En la petición de reducir.',['En todas las valoraciones por igual.','En un rechazo explícito de todo el proyecto.'],'El relato dice que oyó sobre todo reducir y concluyó más de lo que se había solicitado.','She focused on shorten and inferred more than the request stated.'),
 readingQ('¿Qué aportó la compañera?','Contexto omitido en la interpretación inicial.',['Una orden de no preguntar.','Un informe que rechazaba los ejemplos.'],'Recordó los elogios y el alcance concreto de la modificación.','She recalled the praise and the limited scope of the change.'),
 readingQ('¿Por qué quería el coordinador una introducción más breve?','Para reservar espacio a la propuesta ante ese público.',['Porque prohibía todos los argumentos.','Porque nadie conocía el contexto.'],'El público ya conocía contexto; la introducción ocupaba mucho espacio.','The audience knew the background and the introduction used too much space.'),
 readingQ('¿Qué generalización rechaza el texto?','Que toda crítica cortés sea positiva.',['Que pedir aclaraciones pueda ser útil.','Que hubiera más de una estructura posible.'],'Se niega expresamente convertir este caso en una regla sobre toda crítica cortés.','It explicitly rejects making every polite criticism positive by definition.'),
 readingQ('¿Se le dio una única estructura obligatoria?','No, un ejemplo entre posibilidades.',['Sí, una fórmula universal.','Sí, sin posibilidad de conservar nada.'],'El coordinador dio un ejemplo y aclaró que no había una sola estructura válida.','The coordinator offered an example, not the only valid structure.'),
 readingQ('¿Qué aprendizaje destaca el cierre?','Preguntar por el alcance en vez de adivinar intención.',['Interpretar toda frase solo por su tono.','Ignorar siempre las impresiones personales.'],'El cierre valora pedir contexto y límites de una observación.','The ending values asking for context and the scope of a comment.')],task:'Explica qué se afirmó, qué se infirió y qué se aclaró. Añade una pregunta que habrías hecho en la reunión.',taskEn:'Separate what was said, inferred and clarified, then add a question you would have asked.'}
];
extraLibrary.forEach((text,ti)=>text.questions.forEach((q,i)=>{const shift=(ti+i)%3;q.options=q.options.slice(shift).concat(q.options.slice(0,shift));q.answer=(3-shift)%3;}));
